mapper.select:
SELECT

FROM MISSION_LOG
WHERE MEMBER_ID = #{memberId}
  AND ASSIGNMENT_ID = #{assignmentId}

mapper.update:
UPDATE MISSION_LOG
   SET SUBMIT_CONTENT = #{submitContent},
       ATTACHMENT_URL = #{attachmentUrl}
 WHERE ID = #{id}

UPDATE MISSION_LOG
   SET STATUS = #{status},
       REVIEWED_BY = #{reviewedBy},
       REJECT_REASON_CODE = #{rejectReasonCode}
 WHERE ID = #{id}

UPDATE MISSION_LOG
   SET REWARD_AMOUNT = #{rewardAmount}
 WHERE ID = #{id}

UPDATE MISSION_LOG
   SET RESUBMIT_COUNT = RESUBMIT_COUNT + 1
 WHERE ID = #{id}

mapper.select:
SELECT DISTINCT ml.MEMBER_ID AS MEMBER_ID, dma.ASSIGNED_DATE AS ACTIVITY_DATE FROM MISSION_LOG ml JOIN DAILY_MISSION_ASSIGNMENT dma ON dma.ID = ml.ASSIGNMENT_ID WHERE dma.CHALLENGE_ID = #{challengeId} AND ml.STATUS IN
#{status}
ORDER BY ACTIVITY_DATE DESC FETCH FIRST #{limit} ROWS ONLY

mapper.update:
UPDATE MISSION_LOG
   SET REVIEW_REQUESTED_AT = SYSTIMESTAMP
 WHERE ID = #{id}
